              {PRIORITIES.map((p) => (
                <label
                  key={p}
                  className={`flex-1 cursor-pointer rounded-md border px-2 py-2 text-center has-[:focus-visible]:ring-2 has-[:focus-visible]:ring-blue-500 ${
